import os
import re


class SavePythonFile(Component):
    display_name = "Save Python File"
    description = "Save Python code to a .py file."
    icon = "file-code"
    name = "SavePythonFile"

    inputs = [
        MessageTextInput(
            name="filename",
            display_name="Filename",
            value="script.py",
            tool_mode=True,
            required=True,
        ),
        MessageTextInput(
            name="code",
            display_name="Python Code",
            tool_mode=True,
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="output",
            display_name="Result",
            method="save_file",
        )
    ]

    def extract_python(self, text: str) -> str:
        """
        Extract Python code from a markdown response.
        """

        match = re.search(
            r"```(?:python)?\s*(.*?)```",
            text,
            re.DOTALL | re.IGNORECASE,
        )

        if match:
            return match.group(1).strip()

        return text.strip()

    def save_file(self) -> Data:

        try:

            save_dir = r"C:\Projects\Models\agentic\python codes"

            os.makedirs(save_dir, exist_ok=True)

            filename = self.filename.strip()

            if not filename.endswith(".py"):
                filename += ".py"

            filepath = os.path.join(save_dir, filename)

            code = self.extract_python(self.code)

            with open(filepath, "w", encoding="utf-8") as f:
                f.write(code)

            self.status = filepath

            return Data(
                data={
                    "success": True,
                    "path": filepath,
                    "filename": filename,
                    "message": "Python file saved successfully.",
                }
            )

        except Exception as e:

            self.status = str(e)

            return Data(
                data={
                    "success": False,
                    "error": str(e),
                }
            )

