import pyttsx3


class SpeakText(Component):
    display_name = "Speak Text"
    description = "Speak text through the computer speakers."
    icon = "volume-2"
    name = "SpeakText"

    inputs = [
        MessageTextInput(
            name="text",
            display_name="Text",
            value="Hello!",
            tool_mode=True,
            required=True,
        ),
        DropdownInput(
            name="rate",
            display_name="Speed",
            options=["Slow", "Normal", "Fast"],
            value="Normal",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(
            name="output",
            display_name="Result",
            method="speak",
        )
    ]

    def speak(self) -> Data:

        try:

            engine = pyttsx3.init()

            if self.rate == "Slow":
                engine.setProperty("rate", 130)

            elif self.rate == "Fast":
                engine.setProperty("rate", 220)

            else:
                engine.setProperty("rate", 170)

            engine.say(self.text)
            engine.runAndWait()
            engine.stop()

            self.status = "Speech completed."

            return Data(
                data={
                    "success": True,
                    "spoken_text": self.text,
                }
            )

        except Exception as e:

            self.status = str(e)

            return Data(
                data={
                    "success": False,
                    "error": str(e),
                }
            )
